    y = observation.get("player_y", 0)
    # Prefer staying put if nothing else specified
    dx = 0
    dy = 0

    # Resource collection: move toward nearest resource if present
    resources = observation.get("resources", [])
    if resources:
        # resources may be list of [rx, ry] or dicts
        closest = None
        best_dist = None
        for r in resources:
            rx = r[0] if isinstance(r, (list, tuple)) and len(r) >= 2 else r.get("x", 0)
            ry = r[1] if isinstance(r, (list, tuple)) and len(r) >= 2 else r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                closest = (rx, ry)
        if closest is not None:
            rx, ry = closest
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            else:
                dx = 0
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            else:
                dy = 0
            # clip small adjustments to at most one axis per step
            if dx != 0 and dy != 0:
