                    dx = -1
                else:
                    dx = 0
                if ey > y:
                    dy = 1
                elif ey < y:
                    dy = -1
                else:
                    dy = 0
                if dx != 0 and dy != 0:
                    if abs(ex - x) > abs(ey - y):
                        dy = 0
                    else:
                        dx = 0

        # Territory control: if no evaders, move toward majority/target cell if provided
        if dx == 0 and dy == 0:
            territory = observation.get("territory_targets", [])
            if territory:
                t = territory[0]
                tx = t[0] if isinstance(t, (list, tuple)) and len(t) >= 2 else t.get("x", 0)
                ty = t[1] if isinstance(t, (list, tuple)) and len(t) >= 2 else t.get("y", 0)
